function maxOperations(nums, k) {
  const waiting = new Map();
  let operations = 0;

  for (const num of nums) {
    const partner = k - num;
    const count = waiting.get(partner) || 0;
    if (count > 0) {
      waiting.set(partner, count - 1);
      operations++;
    } else {
      waiting.set(num, (waiting.get(num) || 0) + 1);
    }
  }
  return operations;
}

