function maxOperations(nums, k) {
  // Sort, then match the smallest and largest remaining values from both ends.
  const sorted = [...nums].sort((x, y) => x - y);
  let lo = 0;
  let hi = sorted.length - 1;
  let pairs = 0;
  while (lo < hi) {
    const total = sorted[lo] + sorted[hi];
    if (total === k) { pairs++; lo++; hi--; }
    else if (total < k) lo++;
    else hi--;
  }
  return pairs;
}

