    // Large values: plant many complementary pairs among random noise.
    const k = int(2, 1000000000);
    const nums = [];
    while (nums.length < n) {
      if (rand() < 0.6 && k > 1 && nums.length + 2 <= n) {
        const x = int(1, Math.min(k - 1, 1000000000));
        nums.push(x, k - x);
      } else {
        nums.push(int(1, 1000000000));
      }
    }
    for (let i = nums.length - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
    return [nums, k];
  }
  const n = int(1, 10);
  if (roll < 0.75) {
    const k = int(1, 12);
    return [Array.from({ length: n }, () => int(1, 8)), k];
  }
  // Huge values drawn from a few complementary pairs, plus the odd stray value.
  const k = int(2, 1000000000);
  const pool = [];
  for (let i = 0; i < 2; i++) {
    const x = int(1, k - 1);
    pool.push(x, k - x);
  }
  return [Array.from({ length: n }, () => (rand() < 0.15 ? int(1, 1000000000) : pool[int(0, 3)])), k];
